def test_multidisc_resources_require_complete_root_and_missing_refs_fail(tmp_path):
    root = tmp_path / 'roms'; paths = []
    for name in ('a', 'b'):
        path = file(root, f'{name}/game.m3u', b'Disc1.cue\nDisc2.cue\n')
        file(root, f'{name}/Disc1.cue', b'FILE "Disc1.bin" BINARY\n')
        file(root, f'{name}/Disc2.cue', b'FILE "Disc2.bin" BINARY\n')
        file(root, f'{name}/Disc1.bin', b'first disc')
        file(root, f'{name}/Disc2.bin', b'second disc')
        paths.append(game(root, path, name, 'psx', resource_root='/roms/' + name))
    report = audit(tmp_path, paths)
    assert report['duplicates']['content_exact'][0]['game_ids'] == ['a', 'b']
    assert len(report['games'][0]['source_manifest']) == 5
    (root / 'b/Disc2.bin').unlink()
    report = audit(tmp_path, paths)
    assert report['games'][1]['errors'][0]['code'] == 'missing_source'
    assert not report['duplicates']['raw_exact']


