def test_cache_reuses_full_hash_and_invalidates_same_size_preserved_mtime(tmp_path):
    root = tmp_path / 'roms'; a = file(root, 'a.nes', b'AAAA'); b = file(root, 'b.nes', b'AAAA')
    records = [game(root, a, 'a'), game(root, b, 'b')]
    first = audit(tmp_path, records); second = audit(tmp_path, records)
    assert second['progress']['bytes_hashed'] == 0 and second['progress']['cache_hits']
    old = b.stat(); b.write_bytes(b'BBBB'); os.utime(b, ns=(old.st_atime_ns, old.st_mtime_ns))
    third = audit(tmp_path, records)
    assert not third['duplicates']['content_exact']
    assert third['progress']['bytes_hashed'] == 4
    assert first['games'][1]['entry_signature'] != third['games'][1]['entry_signature']


