def test_finish_unit_oversized_raw_files_complete_in_two_bounded_batches(tmp_path):
    root = tmp_path / 'roms'
    budget = 1024**2
    data = b'generated' * 250000  # Several read chunks; larger than the batch limit.
    records = [game(root, file(root, name + '.nes', data), name) for name in ('a', 'b')]
    first = audit(tmp_path, records, max_read_bytes=budget, finish_unit=True)
    assert not first['completed']
    assert first['progress']['files_hashed'] == 1
    assert first['progress']['bytes_hashed'] == len(data)
    assert first['read_budget']['policy'] == 'finish_unit'
    assert first['read_budget']['overrun_bytes'] == len(data) - budget
    assert first['progress']['deferred_unit_bytes'] == len(data)
    second = audit(tmp_path, records, max_read_bytes=budget, finish_unit=True)
    assert second['completed'] and second['progress']['files_hashed'] == 1
    assert second['progress']['bytes_hashed'] == len(data)  # First file came from cache.
    assert second['duplicates']['content_exact'][0]['game_ids'] == ['a', 'b']
    assert second['progress']['oversized_units_started'] == 1


