def test_finish_unit_zip_reserves_all_expanded_members_and_resumes_after_raw_cache(tmp_path):
    root = tmp_path / 'roms'
    path = zipped(root, 'game.zip', [('a.bin', b'A' * 4096), ('b.bin', b'B' * 4096)], zipfile.ZIP_DEFLATED)
    assert path.stat().st_size < 512
    records = [game(root, path, 'a', 'dos')]
    first = audit(tmp_path, records, hash_all=True, max_read_bytes=512, finish_unit=True)
    assert not first['completed']
    assert first['progress']['bytes_hashed'] == path.stat().st_size
    assert first['progress']['zip_members_hashed'] == 0  # No partial decompression.
    assert first['progress']['deferred_unit_bytes'] == 8192
    assert first['games'][0]['raw']['status'] == 'verified'
    second = audit(tmp_path, records, hash_all=True, max_read_bytes=512, finish_unit=True)
    assert second['completed'] and second['progress']['bytes_hashed'] == 8192
    assert second['progress']['zip_members_hashed'] == 2
    assert second['games'][0]['content']['status'] == 'verified'
    third = audit(tmp_path, records, hash_all=True, max_read_bytes=512, finish_unit=True)
    assert third['completed'] and third['progress']['bytes_hashed'] == 0


