def test_forged_zip_member_count_rejected_before_unbounded_allocation(tmp_path):
    root = tmp_path / 'roms'
    path = zipped(root, 'game.zip', [('a.nes', b'a'), ('b.nes', b'b')])
    data = bytearray(path.read_bytes()); offset = data.rfind(b'PK\x05\x06')
    struct.pack_into('<HH', data, offset + 8, 1, 1)
    path.write_bytes(data)
    report = audit(tmp_path, [game(root, path, 'a')], hash_all=True)
    assert report['games'][0]['errors'][0]['code'] == 'invalid_zip'
    assert not report['progress']['zip_members_hashed']


def test_cli_platform_filter_output_locations_and_spreadsheet_escape(tmp_path):
    root = tmp_path / 'roms'
    records = [game(root, file(root, 'a.nes'), 'a'), game(root, file(root, 'b.gb'), 'b', 'gb')]
    records[0]['title'] = '=unsafe-formula'
    catalog = tmp_path / 'catalog.json'; catalog.write_text(json.dumps({'games': records, 'path_prefix': '/roms'}))
    args = ['--catalog', str(catalog), '--rom-root', str(root), '--cache', str(tmp_path / 'cache.sqlite'),
            '--output', str(tmp_path / 'report.json'), '--platform', 'nes', '--rate-mib', '0', '--hash-all']
    assert main(args) == 0
    report = json.loads((tmp_path / 'report.json').read_text())
    assert report['summary']['games'] == 1 and report['games'][0]['title'] == '=unsafe-formula'
    with (tmp_path / 'report.csv').open(encoding='utf-8-sig') as source:
        assert next(csv.DictReader(source))['title'] == "'=unsafe-formula"
    args[args.index('--output') + 1] = str(root / 'report.json')
    with pytest.raises(SystemExit): main(args)


def test_cache_concurrent_process_guard(tmp_path):
    cache = Cache(tmp_path / 'cache.sqlite')
    try:
        with pytest.raises(ValueError, match='Another audit'): Cache(tmp_path / 'cache.sqlite')
    finally: cache.close()
